function table(headers,rows){const line=`| ${headers.join(" | ")} |`,separator=`| ${headers.map(()=>"---").join(" | ")} |`;return [line,separator,...rows.map(row=>`| ${row.map(value=>String(value??"").replaceAll("|","\\|")).join(" | ")} |`)].join("\n");}
