  const decisions=(data.decisions.decisions??[]).filter(item=>(item.requirements??[]).some(id=>requirementIds.has(id)));
  const tests=(data.tests.test_cases??[]).filter(item=>(item.requirements??[]).some(id=>requirementIds.has(id)));
